import { primitives } from './primitives'
import { radiusBase, radiusScale } from './radius'
import { font } from './typography'
import { EColorScheme, semantic } from './semantic'

const GENERATED_HEADER =
  '/* GENERATED by tools/generate-css.ts from src/tokens — edit the tokens, not this file */'

const LIGHT_SELECTORS = ['[data-theme="day"]', '[data-theme="light"]', '.light']

const LIGHT_SELECTOR = LIGHT_SELECTORS.join(', ')

const DARK_VARIANT = `@custom-variant dark (&:where(:not(${LIGHT_SELECTORS.flatMap((selector) => [selector, `${selector} *`]).join(', ')})));`

const IMPORTS = [
  '@import "tailwindcss";',
  '@import "tw-animate-css";',
  '@import "shadcn/tailwind.css";',
]

const UNMAPPED_TOKENS: ReadonlySet<string> = new Set(['scrollbarThumb', 'scrollbarThumbHover'])

export function toKebab(name: string): string {
  return name
    .replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`)
    .replace(/([a-z])(\d)/g, '$1-$2')
}

function block(selector: string, lines: string[]): string {
  return [`${selector} {`, ...lines.map((line) => `  ${line}`), '}'].join('\n')
}

function paletteLines(): string[] {
  const { warm, clay } = primitives.color
  const lines: string[] = []
  for (const [ramp, steps] of Object.entries({ warm, clay })) {
    for (const [step, value] of Object.entries(steps)) {
      lines.push(`--color-${ramp}-${step}: ${value};`)
    }
  }
  return lines
}

function renderInlineThemeBlock(): string {
  const lines: string[] = []
  lines.push(`--font-heading: var(--font-sans);`)
  lines.push(`--font-sans: ${font.sans};`)
  lines.push(`--font-mono: ${font.mono};`)
  lines.push(`--font-display: ${font.display};`)
  for (const name of Object.keys(semantic[EColorScheme.Dark])) {
    if (UNMAPPED_TOKENS.has(name)) continue
    const kebab = toKebab(name)
    lines.push(`--color-${kebab}: var(--${kebab});`)
  }
  for (const [name, factor] of Object.entries(radiusScale)) {
    const value = factor === 1 ? 'var(--radius)' : `calc(var(--radius) * ${factor})`
    lines.push(`--radius-${name}: ${value};`)
  }
  return block('@theme inline', lines)
}

function renderPaletteBlock(): string {
  return block('@theme', paletteLines())
}

function schemeLines(scheme: EColorScheme): string[] {
  return Object.entries(semantic[scheme]).map(([name, value]) => `--${toKebab(name)}: ${value};`)
}

function renderRootBlock(): string {
  return block(':root', [...schemeLines(EColorScheme.Dark), `--radius: ${radiusBase};`])
}

function renderLightBlock(): string {
  return block(LIGHT_SELECTOR, schemeLines(EColorScheme.Light))
}

export function buildThemeCss(): string {
  return [
    GENERATED_HEADER,
    '',
    ...IMPORTS,
    '',
    DARK_VARIANT,
    '',
    renderPaletteBlock(),
    '',
    renderInlineThemeBlock(),
    '',
    renderRootBlock(),
    '',
    renderLightBlock(),
    '',
  ].join('\n')
}
